mapper.sql:
scheme.tenant_id = #{tenantId} AND scheme.deleted = 0

    AND (scheme.scheme_code LIKE CONCAT('%', #{keyword}, '%')
         OR scheme.scheme_name LIKE CONCAT('%', #{keyword}, '%'))


    AND scheme.maintenance_type = #{maintenanceType}

AND scheme.status = #{status}

mapper.select:
SELECT COUNT(*) FROM maintenance_scheme
WHERE tenant_id = #{tenantId} AND scheme_code = #{schemeCode}
AND id != #{excludeId}

SELECT COALESCE(MAX(version_number), 0) + 1
FROM maintenance_scheme_version
WHERE tenant_id = #{tenantId} AND scheme_id = #{schemeId}

SELECT id FROM maintenance_scheme_version
WHERE tenant_id = #{tenantId} AND scheme_id = #{schemeId}
  AND version_number = #{versionNumber}
LIMIT 1

SELECT equipment_category_id FROM maintenance_scheme_category
WHERE tenant_id = #{tenantId} AND scheme_version_id = #{versionId}
ORDER BY equipment_category_id

SELECT equipment_id FROM maintenance_scheme_equipment
WHERE tenant_id = #{tenantId} AND scheme_version_id = #{versionId}
ORDER BY equipment_id

mapper.sql:
task.tenant_id = #{tenantId} AND task.deleted = 0
AND (

  OR (#{scope.selfData} = 1 AND task.assignee_user_id = #{scope.userId})
  OR (#{scope.selfData} = 1 AND EXISTS (
      SELECT 1 FROM maintenance_task_collaborator collaborator
      WHERE collaborator.tenant_id = task.tenant_id
        AND collaborator.task_id = task.id
        AND collaborator.user_id = #{scope.userId}
  ))
)

    AND (task.task_code LIKE CONCAT('%', #{keyword}, '%')
         OR task.scheme_name_snapshot LIKE CONCAT('%', #{keyword}, '%')
         OR e.equipment_code LIKE CONCAT('%', #{keyword}, '%')
         OR e.equipment_name LIKE CONCAT('%', #{keyword}, '%'))

AND task.task_status = #{taskStatus}
AND task.planned_date = #{plannedDate}

    AND (task.assignee_user_id = #{scope.userId}
         OR EXISTS (
            SELECT 1 FROM maintenance_task_collaborator collaborator
            WHERE collaborator.tenant_id = task.tenant_id
              AND collaborator.task_id = task.id
              AND collaborator.user_id = #{scope.userId}
         ))

mapper.select:
SELECT attachment_id FROM maintenance_attachment
WHERE tenant_id = #{tenantId} AND task_result_id = #{taskResultId}
ORDER BY id

mapper.update:
UPDATE maintenance_material_usage
SET deleted = 1, updated_by = #{operatorId}, version = version + 1
WHERE tenant_id = #{tenantId} AND task_id = #{taskId}
  AND id = #{id} AND deleted = 0 AND version = #{version}

UPDATE maintenance_task
SET task_status = #{targetStatus},
    cancel_reason = CASE WHEN #{targetStatus} = 'CANCELLED' THEN #{request.reason}
                         ELSE cancel_reason END,
    void_reason = CASE WHEN #{targetStatus} = 'VOIDED' THEN #{request.reason}
                       ELSE void_reason END,
    updated_by = #{operatorId}, version = version + 1
WHERE tenant_id = #{tenantId} AND id = #{id} AND deleted = 0
  AND version = #{request.version}
  AND task_status NOT IN ('COMPLETED','CANCELLED','VOIDED')
